        updated = 0
        for payload in EXERCISES:
            exercise, was_created = Exercise.objects.update_or_create(
                slug=payload['slug'],
                defaults={
                    'name': payload['name'],
                    'description': payload['description'],
                    'primary_muscle': payload['primary_muscle'],
                    'secondary_muscles': payload.get('secondary_muscles', []),
                    'equipment': payload['equipment'],
                    'difficulty': payload['difficulty'],
                    'exercise_type': payload['exercise_type'],
                    'instructions': payload.get('instructions', []),
                    'common_mistakes': payload.get('common_mistakes', []),
                    'safety_notes': payload.get('safety_notes', []),
                    'default_sets': payload.get('default_sets', 3),
                    'default_reps': payload.get('default_reps', '8-12'),
                    'rest_seconds': payload.get('rest_seconds', 60),
                    'duration_seconds': payload.get('duration_seconds'),
                    'estimated_calories': payload.get('estimated_calories', ''),
                    'video_url': payload.get('video_url', ''),
                    'thumbnail_url': payload.get('thumbnail_url') or THUMBNAIL_URLS.get(payload['slug'], ''),
                    'data_source': payload.get('data_source', 'starter library'),
                    'is_active': True,
                }
            )
            if was_created:
                created += 1
            else:
                updated += 1
        self.stdout.write(self.style.SUCCESS(f'Exercise library seeded: {created} created, {updated} updated'))
